import{_ as s,o as a,c as i,a9 as n}from"./chunks/framework.asyjyako.js";const u=JSON.parse('{"title":"Run bundles","description":"","frontmatter":{},"headers":[],"relativePath":"reference/run-bundles.md","filePath":"reference/run-bundles.md","lastUpdated":null}'),t={name:"reference/run-bundles.md"};function r(l,e,o,d,p,c){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="Run-bundles" tabindex="-1">Run bundles <a class="header-anchor" href="#Run-bundles" aria-label="Permalink to &quot;Run bundles {#Run-bundles}&quot;">​</a></h1><p>A run bundle is a directory holding the measurements, diagnostics and context of one run. The CLI, web interface, VS Code and report tools read the same files.</p><h2 id="What-/1-means" tabindex="-1">What <code>/1</code> means <a class="header-anchor" href="#What-/1-means" aria-label="Permalink to &quot;What \`/1\` means {#What-/1-means}&quot;">​</a></h2><p>Strings such as <code>perfchecker-run-bundle/1</code> identify a <strong>data format</strong> — not a URL, a directory suffix or the package version. The part before the slash is the format name; <code>1</code> is its schema version.</p><ul><li><p><code>perfchecker-suite-plan/1</code> — selected-check plan.</p></li><li><p><code>perfchecker-testitem-run/1</code> — test-item measurements and outcomes.</p></li><li><p><code>perfchecker-run-bundle/1</code> — complete run.</p></li><li><p><code>perfchecker-agent-evidence/1</code> — bounded evidence summary for an advisor.</p></li><li><p><code>perfchecker-query/1</code> — a reusable selection of results.</p></li><li><p><code>perfchecker-query-result/1</code> — query output.</p></li></ul><p>The integer changes only when the contract requires a new reader. If your integration sees an unsupported version, report it — do not guess that it follows version 1.</p><h2 id="Directory-layout" tabindex="-1">Directory layout <a class="header-anchor" href="#Directory-layout" aria-label="Permalink to &quot;Directory layout {#Directory-layout}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run-directory/</span></span>
<span class="line"><span>├─ manifest.json</span></span>
<span class="line"><span>├─ measurement-definitions.json</span></span>
<span class="line"><span>├─ observations.jsonl</span></span>
<span class="line"><span>├─ diagnostics.jsonl</span></span>
<span class="line"><span>├─ artifacts.json</span></span>
<span class="line"><span>├─ integrity.json</span></span>
<span class="line"><span>└─ artifacts/</span></span></code></pre></div><ul><li><p><code>manifest.json</code> — run/attempt identity, state, plan, runtime, environment, timestamps.</p></li><li><p><code>measurement-definitions.json</code> — versioned meaning, unit, method, scope, comparability.</p></li><li><p><code>observations.jsonl</code> — numeric or categorical evidence with comparison keys.</p></li><li><p><code>diagnostics.jsonl</code> — compatibility failures, warnings, attribution findings.</p></li><li><p><code>artifacts.json</code> — metadata for profiles, plots, logs and provider artifacts.</p></li><li><p><code>integrity.json</code> — SHA-256 and byte length for each immutable file.</p></li></ul><h2 id="Julia-API" tabindex="-1">Julia API <a class="header-anchor" href="#Julia-API" aria-label="Permalink to &quot;Julia API {#Julia-API}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PerfChecker</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bundle </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> read_run_bundle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle_directory)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">verify_run_bundle</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle_directory; require_integrity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bundle_passed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bundle_dict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(bundle)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">list_run_bundles</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;perf/results&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; recursive </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p><code>write_run_bundle</code> writes to a temporary sibling and renames atomically. It refuses to overwrite. <code>migrate_run_bundle</code> rewrites supported legacy data into a new destination.</p><h2 id="Identity-and-reuse" tabindex="-1">Identity and reuse <a class="header-anchor" href="#Identity-and-reuse" aria-label="Permalink to &quot;Identity and reuse {#Identity-and-reuse}&quot;">​</a></h2><ul><li><p><code>run_id</code> is the logical experiment; <code>attempt_id</code> is one physical attempt.</p></li><li><p><code>reuse_key</code> describes the normalized plan, runtime and measurement definitions.</p></li><li><p>Reused evidence stays labelled as reused; it never impersonates a fresh run.</p></li></ul><p>Before making a regression decision, a consumer must verify integrity, schema version, completion state, diagnostic severity and measurement-definition identity. <a id="Contents"></a></p>`,15)])])}const k=s(t,[["render",r]]);export{u as __pageData,k as default};
